pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount != 10 ether);
        vm.assume(amount <= address(this).balance);
        vm.deal(address(this), amount == 0 ? 1 : amount);
        (bool ok, ) = address(c).call{value: amount}("");
        assertTrue(!ok, "fallback must revert unless msg.value == 10 ether");
    }
    receive() external payable {}
}
